    if not (IsAtLeast(BaseMight, 30)) then
        evt.StatusText("The practice knight unhorses you at the first pass. Come back with a stronger arm (Might 30).", 6)
        return
    end
    SetValue(MapVar(1), 1)
    AddValue(Experience, 2000)
    evt.StatusText("You unhorse the practice knight in three passes. The crowd cheers. (+2,000 experience)", 6)
end, "The Master of the Lists' challenge")

