-- evt:thing:barbarian_tent_1
RegisterEvent(103, "Barbarian tent", function(continueStep)
    local eventId = 103
    if IsQBitSet(QBit(116060)) then evt.StatusText("Charred poles and wet ash.", 4) return end if continueStep == 1 then XeenQuests.hook("x4.barbarian_camp") return end if continueStep ~= nil then evt.StatusText("You leave the camp standing, for now.", 4) return end AskChoiceWithAnswerSteps(eventId, 3, "You have stumbled upon a Barbarian encampment. Burn?", {{Answer = "Yes", Step = 1}, {Answer = "No", Step = 2}})
end, "Barbarian tent")

