-- evt:pedestals_set
RegisterEvent(176, nil, function()
    if IsAtLeast(MapVar(14), 1) then return end
    if not (((IsAtLeast(MapVar(4), 1)) and (not (IsAtLeast(MapVar(5), 1))) and (IsAtLeast(MapVar(6), 1)) and (not (IsAtLeast(MapVar(7), 1))) and (IsAtLeast(MapVar(8), 1)) and (not (IsAtLeast(MapVar(9), 1))) and (IsAtLeast(MapVar(10), 1)) and (not (IsAtLeast(MapVar(11), 1))) and (not (IsQBitSet(QBit(112101)))))) then
        return
    end
    SetValue(MapVar(14), 1)
    XeenQuests.hook("q-c5.pedestals")
    evt.SimpleMessage("The pedestals hum together, and somewhere under the square a deep note answers.")
end)

